mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xy = rot(time * 0.4) * p.xy;
  float r = length(p.xy);
  float a = atan(p.y, p.x);
  float spiralR = 0.25 * exp(0.18 * a);
  float d = length(vec3(r - spiralR, p.z, 0.0)) - 0.12 * spiralR;
  return d;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.5);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float glow = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    glow += 0.015 / (0.05 + abs(d));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(0.2, 0.8, 1.1) * (0.8 + 0.4 * bass);
  ret = col;
}
